mapper.select:
SELECT *
FROM agent_conversation
WHERE updated_time <= #{asOf}

    AND agent_uid = #{agentUid}


    AND (
        pinned < #{beforePinned}
        OR (pinned = #{beforePinned} AND updated_time < #{beforeUpdatedTime})
        OR (pinned = #{beforePinned} AND updated_time = #{beforeUpdatedTime} AND id < #{beforeId})
    )

ORDER BY pinned DESC, updated_time DESC, id DESC
LIMIT #{limit}
